<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ipv4.address</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 192.168.88.88/24</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
