<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ipv4.dns</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 192.168.88.2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
